const body = $input.first().json.body || $input.first().json;
const question = (body.question || '').toString().trim();
const language = (body.language || 'english').toString().toLowerCase();
const style = (body.style || 'simple').toString().toLowerCase();

if (!question) {
  throw new Error('No question was provided.');
}

const languageInstruction = language === 'hindi'
  ? 'Reply entirely in Hindi, using Devanagari script.'
  : 'Reply entirely in English.';

const styleInstructions = {
  simple: 'Keep the answer short (3-5 sentences), warm, and easy to follow for someone with no background in scripture. Avoid Sanskrit terms unless you immediately explain them in plain words.',
  reflective: 'Write in a gentle, contemplative tone, as a wise friend would speak. End with one short reflective question for the person to sit with, on its own line.',
  scholarly: 'Write a fuller answer (6-10 sentences) that explains the philosophical context (e.g. Karma Yoga, Sankhya, Bhakti) and is suitable for a serious student of the text.'
};

const systemPrompt = `You are a Gita Wisdom guide. You answer only using the teachings of the Bhagavad Gita.
Rules:
- Ground the answer in the Gita's actual teaching, in your own words; do not quote long passages verbatim.
- When one specific verse is clearly the best fit, cite it on its own final line in the exact format "BG <chapter>.<verse>", for example "BG 2.47". Cite at most one verse.
- If no single verse fits cleanly, do not invent a citation - simply omit it.
- Never claim the Gita teaches something it does not.
- ${languageInstruction}
- ${styleInstructions[style] || styleInstructions.simple}`;

return [{
  json: { question, language, style, systemPrompt }
}];

const response = $input.first().json;
let content = '';
try {
  content = response.choices[0].message.content || '';
} catch (e) {
  content = "I couldn't form an answer just now. Please try again in a moment.";
}

content = content.trim();

let citation = null;
const match = content.match(/BG\s?(\d{1,2})\.(\d{1,3})\s*$/i);
if (match) {
  citation = `BG ${match[1]}.${match[2]}`;
  content = content.replace(/\n?BG\s?\d{1,2}\.\d{1,3}\s*$/i, '').trim();
}

const model = response.model || null;

return [{ json: { answer: content, citation, model } }];
